import{_ as s,o as n,c as t,ag as p}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"伦理学：我们应该如何行动","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/philosophy/ethics.md","filePath":"topics/philosophy/ethics.md"}'),e={name:"topics/philosophy/ethics.md"};function l(i,a,o,d,r,c){return n(),t("div",null,[...a[0]||(a[0]=[p(`<h1 id="伦理学-我们应该如何行动" tabindex="-1">伦理学：我们应该如何行动 <a class="header-anchor" href="#伦理学-我们应该如何行动" aria-label="Permalink to &quot;伦理学：我们应该如何行动&quot;">​</a></h1><blockquote><p>伦理学（Ethics）研究&quot;应该如何行动&quot;——这是哲学中最&quot;接地气&quot;的分支。功利主义说&quot;最大多数人的最大幸福&quot;；康德说&quot;绝对命令&quot;；亚里士多德说&quot;幸福即德性活动&quot;；儒家说&quot;仁义礼智信&quot;。这些理论不只是书斋里的争论，而是我们每天都在面对的选择：利益与道德冲突时怎么办？道德困境如何决策？</p><p>整理日期：2026-06-17</p></blockquote><hr><h2 id="一、伦理学的核心问题" tabindex="-1">一、伦理学的核心问题 <a class="header-anchor" href="#一、伦理学的核心问题" aria-label="Permalink to &quot;一、伦理学的核心问题&quot;">​</a></h2><h3 id="_1-1-什么是-对错" tabindex="-1">1.1 什么是&quot;对错&quot; <a class="header-anchor" href="#_1-1-什么是-对错" aria-label="Permalink to &quot;1.1 什么是&quot;对错&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>伦理学追问：</span></span>
<span class="line"><span>- 什么是善？什么是恶？</span></span>
<span class="line"><span>- 我们为什么要道德？</span></span>
<span class="line"><span>- 道德义务的来源是什么？</span></span>
<span class="line"><span>- 利益与道德冲突时，哪个优先？</span></span></code></pre></div><h3 id="_1-2-伦理学的三个层次" tabindex="-1">1.2 伦理学的三个层次 <a class="header-anchor" href="#_1-2-伦理学的三个层次" aria-label="Permalink to &quot;1.2 伦理学的三个层次&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>问题</th><th>回答</th></tr></thead><tbody><tr><td><strong>元伦理学</strong></td><td>&quot;道德&quot;究竟是什么意思？道德判断有真假吗？</td><td>道德语言的分析</td></tr><tr><td><strong>规范伦理学</strong></td><td>什么是正确的行为准则？</td><td>提出道德原则</td></tr><tr><td><strong>应用伦理学</strong></td><td>具体情境下该怎么做？</td><td>堕胎、安乐死、AI伦理等</td></tr></tbody></table><hr><h2 id="二、功利主义-效果论" tabindex="-1">二、功利主义：效果论 <a class="header-anchor" href="#二、功利主义-效果论" aria-label="Permalink to &quot;二、功利主义：效果论&quot;">​</a></h2><h3 id="_2-1-边沁-最大幸福原则" tabindex="-1">2.1 边沁：最大幸福原则 <a class="header-anchor" href="#_2-1-边沁-最大幸福原则" aria-label="Permalink to &quot;2.1 边沁：最大幸福原则&quot;">​</a></h3><p><strong>杰里米·边沁</strong>（1748-1832）创立功利主义。</p><p><strong>核心原则：</strong></p><blockquote><p>最大多数人的最大幸福。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>行动对错的标准 = 后果</span></span>
<span class="line"><span>→ 增加幸福 = 对</span></span>
<span class="line"><span>→ 减少幸福 = 错</span></span>
<span class="line"><span></span></span>
<span class="line"><span>所有人都平等计算</span></span>
<span class="line"><span>→ 一个人痛苦 vs 一万人痛苦 → 应该避免一万人痛苦</span></span></code></pre></div><p><strong>边沁的&quot;幸福计算&quot;：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>问题</th></tr></thead><tbody><tr><td>强度</td><td>有多幸福/痛苦？</td></tr><tr><td>持续时间</td><td>幸福/痛苦持续多久？</td></tr><tr><td>确定程度</td><td>确定还是不确定？</td></tr><tr><td>远近</td><td>立即发生还是以后发生？</td></tr><tr><td>纯度</td><td>幸福中有多少痛苦？</td></tr><tr><td>范围</td><td>影响到多少人？</td></tr></tbody></table><h3 id="_2-2-密尔-更高-更低快乐" tabindex="-1">2.2 密尔：更高/更低快乐 <a class="header-anchor" href="#_2-2-密尔-更高-更低快乐" aria-label="Permalink to &quot;2.2 密尔：更高/更低快乐&quot;">​</a></h3><p><strong>约翰·斯图尔特·密尔</strong>（1806-1873）发展了更精细的功利主义。</p><p><strong>密尔的升级：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>边沁版功利主义：所有快乐平等计算</span></span>
<span class="line"><span>密尔版功利主义：快乐有质量差异</span></span>
<span class="line"><span></span></span>
<span class="line"><span>更高快乐（如艺术、智识）&gt; 较低快乐（如吃睡）</span></span>
<span class="line"><span>↓ </span></span>
<span class="line"><span>功利主义也应该追求更高质量的精神幸福</span></span></code></pre></div><p><strong>密尔的名言：</strong></p><blockquote><p>&quot;做一个不满足的苏格拉底，胜过做一只满足的猪。&quot;</p></blockquote><p>（苏格拉底虽然痛苦思考，但精神快乐比猪的感官快乐更有价值。）</p><h3 id="_2-3-功利主义的优缺点" tabindex="-1">2.3 功利主义的优缺点 <a class="header-anchor" href="#_2-3-功利主义的优缺点" aria-label="Permalink to &quot;2.3 功利主义的优缺点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>重视所有人的福祉</td><td>短期效果 vs 长期效果的冲突</td></tr><tr><td>灵活务实</td><td>可能牺牲少数人利益</td></tr><tr><td>与现代民主精神契合</td><td>难以量化幸福</td></tr><tr><td>推动社会改革（废奴、福利制度）</td><td>道德直觉有时反对&quot;多数暴政&quot;</td></tr></tbody></table><hr><h2 id="三、义务论-康德的道德哲学" tabindex="-1">三、义务论：康德的道德哲学 <a class="header-anchor" href="#三、义务论-康德的道德哲学" aria-label="Permalink to &quot;三、义务论：康德的道德哲学&quot;">​</a></h2><h3 id="_3-1-康德的绝对命令" tabindex="-1">3.1 康德的绝对命令 <a class="header-anchor" href="#_3-1-康德的绝对命令" aria-label="Permalink to &quot;3.1 康德的绝对命令&quot;">​</a></h3><p><strong>伊曼努尔·康德</strong>（1724-1804）的伦理学是义务论的代表。</p><p><strong>绝对命令（Categorical Imperative）：</strong></p><blockquote><p>&quot;只能按照你能同时愿意它成为普遍法则的行动准则行动。&quot;</p></blockquote><p><strong>什么意思？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一步：你的行动准则是什么？</span></span>
<span class="line"><span>  例：我可以说谎，为了救一个人</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>第二步：如果这成为普遍法则，会怎样？</span></span>
<span class="line"><span>  如果所有人都说谎&quot;为了救人&quot; → 没有人相信任何人 → 谎言失效 → 没人能得救</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三步：所以，说谎是不道德的。</span></span></code></pre></div><p><strong>康德的测试：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>测试方法：把行动准则普遍化</span></span>
<span class="line"><span>- 能普遍化吗？→ 不能 → 不道德</span></span>
<span class="line"><span>- 能普遍化吗？→ 能 → 道德</span></span></code></pre></div><h3 id="_3-2-绝对命令的另一个表述" tabindex="-1">3.2 绝对命令的另一个表述 <a class="header-anchor" href="#_3-2-绝对命令的另一个表述" aria-label="Permalink to &quot;3.2 绝对命令的另一个表述&quot;">​</a></h3><blockquote><p>&quot;永远把人（自己或他人）当作目的，而不是仅仅当作手段。&quot;</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不道德的例子：</span></span>
<span class="line"><span>- 撒谎欺骗他人 → 把他人当手段（骗他做事）</span></span>
<span class="line"><span>- 杀人 → 把人的生命当手段（为了某个目的杀人）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>道德的要求：</span></span>
<span class="line"><span>- 尊重每个人的内在价值</span></span>
<span class="line"><span>- 不利用他人</span></span>
<span class="line"><span>- 诚实对待</span></span></code></pre></div><h3 id="_3-3-康德-vs-功利主义" tabindex="-1">3.3 康德 vs 功利主义 <a class="header-anchor" href="#_3-3-康德-vs-功利主义" aria-label="Permalink to &quot;3.3 康德 vs 功利主义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>功利主义</th><th>康德义务论</th></tr></thead><tbody><tr><td><strong>道德标准</strong></td><td>后果</td><td>动机/原则</td></tr><tr><td><strong>核心问题</strong></td><td>结果好不好？</td><td>原则对不对？</td></tr><tr><td><strong>撒谎</strong></td><td>如果能救更多人说谎可以接受</td><td>撒谎永远不对</td></tr><tr><td><strong>道德性质</strong></td><td>目的论（结果导向）</td><td>义务论（原则导向）</td></tr></tbody></table><p><strong>两者的张力：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>功利主义：&quot;911劫机&quot;事件中，乘客反击可能杀死劫机者，救更多人 → 应该鼓励</span></span>
<span class="line"><span>康德义务论：杀掉无辜的人永远不对，即使能救更多人</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 这就是道德哲学的核心张力：结果 vs 原则</span></span></code></pre></div><hr><h2 id="四、德性伦理学-亚里士多德" tabindex="-1">四、德性伦理学：亚里士多德 <a class="header-anchor" href="#四、德性伦理学-亚里士多德" aria-label="Permalink to &quot;四、德性伦理学：亚里士多德&quot;">​</a></h2><h3 id="_4-1-亚里士多德的幸福论" tabindex="-1">4.1 亚里士多德的幸福论 <a class="header-anchor" href="#_4-1-亚里士多德的幸福论" aria-label="Permalink to &quot;4.1 亚里士多德的幸福论&quot;">​</a></h3><p><strong>亚里士多德</strong>（公元前384-前322）的伦理学聚焦于&quot;幸福&quot;（Eudaimonia）。</p><blockquote><p>&quot;幸福是灵魂合乎德性的活动。&quot;</p></blockquote><p><strong>什么是Eudaimonia？</strong></p><ul><li>中文译&quot;幸福&quot;，但更准确的意思是&quot; flourishing&quot;（蓬勃发展）</li><li>不是快感，不是财富，而是人作为人的充分实现</li></ul><h3 id="_4-2-德性-品格的优点" tabindex="-1">4.2 德性：品格的优点 <a class="header-anchor" href="#_4-2-德性-品格的优点" aria-label="Permalink to &quot;4.2 德性：品格的优点&quot;">​</a></h3><p><strong>德性（Virtue）</strong> 是品格的优点，位于两个极端之间：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>德性 = 两个极端之间的中道</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：勇气</span></span>
<span class="line"><span>过度（鲁莽） ← 勇气 → 不及（懦弱）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：慷慨</span></span>
<span class="line"><span>过度（挥霍） ← 慷慨 → 不及（吝啬）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：诚实</span></span>
<span class="line"><span>过度（吹牛） ← 诚实 → 不及（欺骗）</span></span></code></pre></div><h3 id="_4-3-德性如何培养" tabindex="-1">4.3 德性如何培养 <a class="header-anchor" href="#_4-3-德性如何培养" aria-label="Permalink to &quot;4.3 德性如何培养&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>亚里士多德的答案：通过习惯</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我们不是生来有德性</span></span>
<span class="line"><span>我们通过做有德性的事 → 成为有德性的人</span></span>
<span class="line"><span></span></span>
<span class="line"><span>就像学钢琴：</span></span>
<span class="line"><span>弹钢琴让人成为钢琴家 → 弹钢琴的动作形成习惯 → 成为钢琴家</span></span>
<span class="line"><span></span></span>
<span class="line"><span>做勇敢的事 → 习惯勇敢 → 成为勇敢的人</span></span></code></pre></div><h3 id="_4-4-德性伦理学的现代复兴" tabindex="-1">4.4 德性伦理学的现代复兴 <a class="header-anchor" href="#_4-4-德性伦理学的现代复兴" aria-label="Permalink to &quot;4.4 德性伦理学的现代复兴&quot;">​</a></h3><p>20世纪80年代，阿奎那·麦金太尔等哲学家复兴了德性伦理学。</p><p><strong>德性伦理学的特点：</strong></p><table tabindex="0"><thead><tr><th>特点</th><th>说明</th></tr></thead><tbody><tr><td><strong>关注人</strong></td><td>问&quot;你是什么样的人&quot;，而非&quot;你应该做什么&quot;</td></tr><tr><td><strong>关注品格</strong></td><td>德性是稳定的品格特质</td></tr><tr><td><strong>强调习惯</strong></td><td>道德是长期养成的品格</td></tr><tr><td><strong>重视情境</strong></td><td>具体情境决定何为中道</td></tr></tbody></table><hr><h2 id="五、存在主义伦理学-萨特" tabindex="-1">五、存在主义伦理学：萨特 <a class="header-anchor" href="#五、存在主义伦理学-萨特" aria-label="Permalink to &quot;五、存在主义伦理学：萨特&quot;">​</a></h2><h3 id="_5-1-萨特的核心命题" tabindex="-1">5.1 萨特的核心命题 <a class="header-anchor" href="#_5-1-萨特的核心命题" aria-label="Permalink to &quot;5.1 萨特的核心命题&quot;">​</a></h3><p><strong>让-保罗·萨特</strong>（1905-1980）提出存在主义伦理学的核心：</p><blockquote><p>&quot;存在先于本质。&quot;</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统观点：</span></span>
<span class="line"><span>  人有固定的&quot;本质&quot;（被造物主设计）→ 然后按本质行动</span></span>
<span class="line"><span></span></span>
<span class="line"><span>存在主义：</span></span>
<span class="line"><span>  人先存在 → 自己创造自己的&quot;本质&quot; → 通过选择定义自己</span></span></code></pre></div><h3 id="_5-2-自由与责任" tabindex="-1">5.2 自由与责任 <a class="header-anchor" href="#_5-2-自由与责任" aria-label="Permalink to &quot;5.2 自由与责任&quot;">​</a></h3><p><strong>萨特的&quot;绝对自由&quot;：</strong></p><blockquote><p>&quot;人是注定自由的。&quot; &quot;没有借口——你是你自己的选择。&quot;</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>含义：</span></span>
<span class="line"><span>- 你无法怪罪于本性、环境、命运</span></span>
<span class="line"><span>- 每个选择都是你对&quot;人应该是什么&quot;的定义</span></span>
<span class="line"><span>- 你的选择也为全人类做出示范</span></span></code></pre></div><p><strong>萨特的&quot;恶心&quot;：</strong></p><blockquote><p>自由是沉重的——你无法逃避选择，也无法为选择找借口。</p></blockquote><h3 id="_5-3-存在主义伦理学的特点" tabindex="-1">5.3 存在主义伦理学的特点 <a class="header-anchor" href="#_5-3-存在主义伦理学的特点" aria-label="Permalink to &quot;5.3 存在主义伦理学的特点&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>特点 → 含义</span></span>
<span class="line"><span></span></span>
<span class="line"><span>自由选择 → 没人替你做决定</span></span>
<span class="line"><span>责任承担 → 为选择承担全部后果</span></span>
<span class="line"><span>本真性 → 做真正的自己，不随大流</span></span>
<span class="line"><span>承认焦虑 → 自由带来焦虑是正常的</span></span></code></pre></div><hr><h2 id="六、中国伦理学-儒家的道德体系" tabindex="-1">六、中国伦理学：儒家的道德体系 <a class="header-anchor" href="#六、中国伦理学-儒家的道德体系" aria-label="Permalink to &quot;六、中国伦理学：儒家的道德体系&quot;">​</a></h2><h3 id="_6-1-儒家五常" tabindex="-1">6.1 儒家五常 <a class="header-anchor" href="#_6-1-儒家五常" aria-label="Permalink to &quot;6.1 儒家五常&quot;">​</a></h3><p><strong>仁义礼智信</strong>是儒家伦理的核心范畴：</p><table tabindex="0"><thead><tr><th>德目</th><th>含义</th><th>现实应用</th></tr></thead><tbody><tr><td><strong>仁</strong></td><td>仁者爱人，推己及人</td><td>关爱他人，换位思考</td></tr><tr><td><strong>义</strong></td><td>应当做的事，合乎道德</td><td>义利之辨，见利思义</td></tr><tr><td><strong>礼</strong></td><td>社会规范，礼仪秩序</td><td>尊重规则，礼貌待人</td></tr><tr><td><strong>智</strong></td><td>明辨是非，理性判断</td><td>批判性思维，辨别善恶</td></tr><tr><td><strong>信</strong></td><td>诚实守信，言出必行</td><td>建立信任，言行一致</td></tr></tbody></table><h3 id="_6-2-义利之辨" tabindex="-1">6.2 义利之辨 <a class="header-anchor" href="#_6-2-义利之辨" aria-label="Permalink to &quot;6.2 义利之辨&quot;">​</a></h3><p><strong>儒家的义利观：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>孔子：&quot;君子喻于义，小人喻于利&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不是反对利益</span></span>
<span class="line"><span>而是：利益要合乎道义</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 君子取财有道</span></span>
<span class="line"><span>→ 见利忘义是小人</span></span></code></pre></div><p><strong>现代理解：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>义利合一：</span></span>
<span class="line"><span>- 合乎道德的利益是正当的</span></span>
<span class="line"><span>- 不道德的手段获取利益不可取</span></span>
<span class="line"><span>- 长期来看，道德是最大的&quot;利&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>义利冲突时：</span></span>
<span class="line"><span>- 孟子：&quot;舍生取义&quot;</span></span>
<span class="line"><span>- 必要时牺牲生命维护道德原则</span></span></code></pre></div><h3 id="_6-3-儒家与康德的对话" tabindex="-1">6.3 儒家与康德的对话 <a class="header-anchor" href="#_6-3-儒家与康德的对话" aria-label="Permalink to &quot;6.3 儒家与康德的对话&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>儒家</th><th>康德</th></tr></thead><tbody><tr><td><strong>道德基础</strong></td><td>人性本善 → 扩充善端</td><td>理性 → 发现道德法则</td></tr><tr><td><strong>道德标准</strong></td><td>仁 → 推己及人</td><td>绝对命令 → 普遍化原则</td></tr><tr><td><strong>修养方法</strong></td><td>内省、修身</td><td>理性自律</td></tr><tr><td><strong>共同点</strong></td><td>都强调道德的普遍性</td><td>都强调原则高于利益</td></tr></tbody></table><hr><h2 id="七、道德困境的决策框架" tabindex="-1">七、道德困境的决策框架 <a class="header-anchor" href="#七、道德困境的决策框架" aria-label="Permalink to &quot;七、道德困境的决策框架&quot;">​</a></h2><h3 id="_7-1-经典道德困境" tabindex="-1">7.1 经典道德困境 <a class="header-anchor" href="#_7-1-经典道德困境" aria-label="Permalink to &quot;7.1 经典道德困境&quot;">​</a></h3><p><strong>电车难题：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>情景1：推一个人下去挡车 → 救5人 → 死1人</span></span>
<span class="line"><span>情景2：不推 → 5人死</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功利主义：推（救更多生命）</span></span>
<span class="line"><span>康德义务论：不推（不能把人当手段）</span></span></code></pre></div><p><strong>道德直觉 vs 道德理论的冲突：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>困境：</span></span>
<span class="line"><span>- 道德直觉说&quot;不推&quot;（电车难题）</span></span>
<span class="line"><span>- 功利主义计算说&quot;推&quot;（数字更大）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可能的解决：</span></span>
<span class="line"><span>- 承认直觉不完美，但也不可完全忽视</span></span>
<span class="line"><span>- 追问直觉背后的理由</span></span>
<span class="line"><span>- 理论需要与直觉对话</span></span></code></pre></div><h3 id="_7-2-决策步骤" tabindex="-1">7.2 决策步骤 <a class="header-anchor" href="#_7-2-决策步骤" aria-label="Permalink to &quot;7.2 决策步骤&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>面对道德困境的步骤：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 识别道德维度</span></span>
<span class="line"><span>   - 谁受影响？利益如何？</span></span>
<span class="line"><span>   - 涉及哪些价值？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 列出可能的选项</span></span>
<span class="line"><span>   - 不要只想到A和B</span></span>
<span class="line"><span>   - 思考有没有第三选项</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 评估每个选项</span></span>
<span class="line"><span>   - 功利主义：后果如何？幸福/痛苦总量？</span></span>
<span class="line"><span>   - 康德义务论：原则是否普遍化？</span></span>
<span class="line"><span>   - 德性伦理学：这是有德性的人会做的事吗？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 考虑情境特殊性</span></span>
<span class="line"><span>   - 有没有特殊义务超越一般原则？</span></span>
<span class="line"><span>   - 承诺、关系、角色带来什么责任？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. 做出决定并承担责任</span></span>
<span class="line"><span>   - 承认道德判断的复杂性</span></span>
<span class="line"><span>   - 为决定承担后果</span></span></code></pre></div><hr><h2 id="八、伦理学与工作生活" tabindex="-1">八、伦理学与工作生活 <a class="header-anchor" href="#八、伦理学与工作生活" aria-label="Permalink to &quot;八、伦理学与工作生活&quot;">​</a></h2><h3 id="_8-1-职场伦理" tabindex="-1">8.1 职场伦理 <a class="header-anchor" href="#_8-1-职场伦理" aria-label="Permalink to &quot;8.1 职场伦理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>功利主义考量</th><th>康德义务论考量</th><th>儒家考量</th></tr></thead><tbody><tr><td><strong>裁员</strong></td><td>裁少数，保多数</td><td>不能把人当工具，要尊重</td><td>义利兼顾，考虑社会责任</td></tr><tr><td><strong>说谎</strong></td><td>为救人说谎可接受</td><td>撒谎永远不对</td><td>看动机与后果</td></tr><tr><td><strong>竞争</strong></td><td>优胜劣汰</td><td>不正当手段不行</td><td>义利之争</td></tr></tbody></table><h3 id="_8-2-利益与道德的取舍" tabindex="-1">8.2 利益与道德的取舍 <a class="header-anchor" href="#_8-2-利益与道德的取舍" aria-label="Permalink to &quot;8.2 利益与道德的取舍&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>利益 vs 道德 = 短期 vs 长期的取舍</span></span>
<span class="line"><span></span></span>
<span class="line"><span>短期看：道德可能吃亏</span></span>
<span class="line"><span>长期看：道德是最大的利</span></span>
<span class="line"><span></span></span>
<span class="line"><span>诚信经营 → 长期品牌价值</span></span>
<span class="line"><span>真诚待人 → 长期人际关系</span></span>
<span class="line"><span>正当竞争 → 行业健康发展</span></span>
<span class="line"><span></span></span>
<span class="line"><span>道德不是成本，是投资</span></span></code></pre></div><hr><h2 id="九、伦理学总结" tabindex="-1">九、伦理学总结 <a class="header-anchor" href="#九、伦理学总结" aria-label="Permalink to &quot;九、伦理学总结&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三大伦理学派的比较</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功利主义：</span></span>
<span class="line"><span>  核心：最大幸福</span></span>
<span class="line"><span>  标准：后果</span></span>
<span class="line"><span>  方法：计算</span></span>
<span class="line"><span></span></span>
<span class="line"><span>义务论：</span></span>
<span class="line"><span>  核心：道德法则</span></span>
<span class="line"><span>  标准：原则</span></span>
<span class="line"><span>  方法：检验普遍化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>德性伦理学：</span></span>
<span class="line"><span>  核心：美好生活</span></span>
<span class="line"><span>  标准：品格</span></span>
<span class="line"><span>  方法：习惯养成</span></span>
<span class="line"><span></span></span>
<span class="line"><span>儒家伦理：</span></span>
<span class="line"><span>  核心：仁</span></span>
<span class="line"><span>  标准：义</span></span>
<span class="line"><span>  方法：修身</span></span>
<span class="line"><span></span></span>
<span class="line"><span>共同指向：</span></span>
<span class="line"><span>  道德不是约束，而是人的充分实现</span></span></code></pre></div><hr><p><em>整理日期：2026-06-17</em><em>建议交叉阅读：</em></p><ul><li><em>西方哲学（康德、亚里士多德的伦理学传统）</em></li><li><em>中国传统哲学（儒家伦理的深入展开）</em></li><li><em>实用主义哲学（杜威的民主伦理学）</em></li><li><em>认识论与科学哲学（批判性思维在道德判断中的应用）</em></li></ul>`,106)])])}const b=s(e,[["render",l]]);export{u as __pageData,b as default};
